// CORE: Mission Orchestrator — logic in lib/orchestrator.js (unit-tested by scripts/test.js).
// The live site config lives in global context (edited from setup.html); site.json is only the seed.
const { orchestrator: O, seed } = global.get('mekoniq');
const site = global.get('site') || seed;
const now = Date.now();
const st = flow.get('orch') || O.init(site, now);
let input;
if (msg.topic === 'adapter') input = { source: 'adapter', data: msg.payload };
else {
    try { input = { source: 'ui', data: JSON.parse(msg.payload), session: msg._session, seed }; } catch (e) { return null; }
}
const r = O.handle(st, site, input, now);
flow.set('orch', st);
if (r.site) global.set('site', r.site);
return [
    r.ui.map(u => u.session ? { payload: u.payload, _session: u.session } : { payload: u.payload }),
    r.cmds.map(cmd => ({ topic: 'cmd', payload: cmd }))
];

// ADAPTER: robot simulator (web demo / robots without a driver). Same contract as the Valetudo adapter.
const { simulator: S, seed } = global.get('mekoniq');
const site = global.get('site') || seed;
const sim = flow.get('sim') || S.init(site);
const events = S.handle(sim, site, msg.topic === 'tick' ? { cmd: 'tick' } : msg.payload, Date.now());
flow.set('sim', sim);
return [events.map(e => ({ topic: 'adapter', payload: e }))];

// ADAPTER: Valetudo robot over MQTT — logic in lib/valetudo.js (unit-tested by scripts/test-valetudo.js).
const { valetudo: V, seed } = global.get('mekoniq');
const site = global.get('site') || seed;
const st = flow.get('val') || V.init(site);
const input = msg.status ? { cmd: 'link', up: msg.status.fill === 'green' }   // MQTT broker connection
    : msg.topic === 'tick' ? { cmd: 'tick' }
    : Buffer.isBuffer(msg.payload) || typeof msg.payload === 'string' ? { cmd: 'mqtt', topic: msg.topic, payload: msg.payload }
    : msg.payload;
const r = V.handle(st, site, input, Date.now());
flow.set('val', st);
for (const [id, m] of Object.entries(r.maps || {})) global.set('vmap:' + id, m, 'memory');   // robot maps: RAM only (Task 9 serves them)
return [r.events.map(e => ({ topic: 'adapter', payload: e })), r.mqtt.map(m => ({ topic: m.topic, payload: m.payload }))];
